-- create-table COUNTRIES
CREATE TABLE "COUNTRIES" (
  "COUNTRY_CODE" VARCHAR(2) NOT NULL,
  "NAME" VARCHAR(80) NOT NULL,
  "CURRENCY" VARCHAR(3),
  CONSTRAINT "COUNTRIES#PK" PRIMARY KEY ("COUNTRY_CODE")
);

-- create-table COMPANIES
CREATE TABLE "COMPANIES" (
  "/RT/TENANT" VARCHAR(16) NOT NULL,
  "COMPANY_ID" VARCHAR(10) NOT NULL,
  "NAME" VARCHAR(80) NOT NULL,
  "COUNTRY" VARCHAR(2) NOT NULL,
  "STATUS" VARCHAR(10) NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" NUMERIC(15,2),
  "FOUNDED_ON" DATE,
  "/TROTTO/OTTO_ID" VARCHAR(20),
  CONSTRAINT "COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "COUNTRIES" ("COUNTRY_CODE") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "COMPANIES#CK#STATUS" CHECK ("STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))
);

-- create-table BANK_ACCOUNTS
CREATE TABLE "BANK_ACCOUNTS" (
  "/RT/TENANT" VARCHAR(16) NOT NULL,
  "COMPANY_ID" VARCHAR(10) NOT NULL,
  "ACCOUNT_NO" INTEGER NOT NULL,
  "IBAN" VARCHAR(34) NOT NULL,
  "BALANCE" NUMERIC(15,2) NOT NULL DEFAULT 0.00,
  "OPENED_AT" TIMESTAMPTZ,
  CONSTRAINT "BANK_ACCOUNTS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO"),
  CONSTRAINT "BANK_ACCOUNTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "BANK_ACCOUNTS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "COMPANIES" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table EXCHANGE_RATES
CREATE TABLE "EXCHANGE_RATES" (
  "FROM_CURRENCY" VARCHAR(3) NOT NULL,
  "TO_CURRENCY" VARCHAR(3) NOT NULL,
  "VALID_FROM" DATE NOT NULL,
  "RATE" NUMERIC(15,6) NOT NULL,
  CONSTRAINT "EXCHANGE_RATES#PK" PRIMARY KEY ("FROM_CURRENCY", "TO_CURRENCY", "VALID_FROM")
);

-- create-table OTTO_CONNECTIONS
CREATE TABLE "OTTO_CONNECTIONS" (
  "/RT/TENANT" VARCHAR(16) NOT NULL,
  "COMPANY_ID" VARCHAR(10) NOT NULL,
  "ENDPOINT" TEXT NOT NULL,
  "ACTIVE" BOOLEAN NOT NULL DEFAULT TRUE,
  CONSTRAINT "OTTO_CONNECTIONS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "OTTO_CONNECTIONS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "OTTO_CONNECTIONS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "COMPANIES" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table PAYMENTS
CREATE TABLE "PAYMENTS" (
  "/RT/TENANT" VARCHAR(16) NOT NULL,
  "COMPANY_ID" VARCHAR(10) NOT NULL,
  "ACCOUNT_NO" INTEGER NOT NULL,
  "PAYMENT_NO" BIGINT NOT NULL,
  "AMOUNT" NUMERIC(15,2) NOT NULL,
  "CURRENCY" VARCHAR(3) NOT NULL,
  "BOOKED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "PAYMENTS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO", "PAYMENT_NO"),
  CONSTRAINT "PAYMENTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "PAYMENTS#FK#ACCOUNT" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO") REFERENCES "BANK_ACCOUNTS" ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO") DEFERRABLE INITIALLY IMMEDIATE
);

